# tiles: O (2x2), L = 2x2 minus one corner
def gen_tiles(r,c):
    sq=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
    yield ('O',sq)
    for i in range(4):
        yield ('L%d'%i,[sq[j] for j in range(4) if j!=i])  # i=missing corner: 0=NW,1=NE,2=SW,3=SE
cells=sorted(cells)
sols=[]
def solve(remaining, acc):
    if not remaining:
        sols.append(list(acc)); return
    r,c=min(remaining)
    for name,t in gen_tiles(r,c):
        if all(p in remaining for p in t):
            solve(remaining-set(t), acc+[(name,t)])
