def all_tiles():
    ts={}
    for r in range(-1,7):
        for c in range(-1,7):
            sq=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            if all(p in cells for p in sq): ts.setdefault('O',[]).append(tuple(sorted(sq)))
            for i in range(4):
                t=tuple(sorted(sq[j] for j in range(4) if j!=i))
                if all(p in cells for p in t): ts.setdefault('L%d'%i,[]).append(t)
    return ts
T=all_tiles()
sols=[]
def solve(rem,acc):
    if not rem: sols.append(list(acc)); return
    a=min(rem)
    for name,tl in T.items():
        for t in tl:
            if a in t and all(p in rem for p in t):
                solve(rem-set(t),acc+[(name,t)])
